"""SS78: write-time negative keys generated by the frozen base model.

For every edit prompt of the dev split and the two N=1000 test stores, the base model
writes five questions about the same subject that ask for different but related
information (greedy decoding). Only the edit prompt and the subject are used, which are
available when a fact is added.

    .venv/bin/python experiments/sandbox/live_learning/confirm/gen_negkeys.py
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "text"))

from router_v4 import find_subject  # noqa: E402
from router_v4_calibrate import build_dev  # noqa: E402

CONFIRM = Path("results/live_learning/confirm")
N_KEYS = 5
SYSTEM = "You rewrite prompts."
USER = (
    'Here is a question about "{subject}": {probe}\n'
    'Write five questions about "{subject}" that ask for different but related information, '
    "for example another place, date, language, organization, person or category connected "
    "to it. None of them may ask for the same information as the question above. Keep the "
    'name "{subject}" exactly as written. Write one question per line, without numbering.'
)
_BULLET = re.compile(r"^\s*(?:[-*•]|\d+[.)])\s*")


def parse(text: str, probe: str, subject: str) -> list[str]:
    out = []
    for line in text.splitlines():
        line = _BULLET.sub("", line).strip().strip('"').strip()
        if not line or line.rstrip("?") == probe.strip().rstrip("?") or line in out:
            continue
        if find_subject(line, subject) is None:
            continue
        out.append(line)
        if len(out) == N_KEYS:
            break
    return out


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=str(CONFIRM / "generated_negkeys.json"))
    ap.add_argument("--batch", type=int, default=32)
    args = ap.parse_args(argv)
    if Path(args.out).exists():
        ap.error(f"refusing to overwrite {args.out}")

    import torch
    from routed_eval import MANIFEST_PATH
    from transformers import AutoModelForCausalLM, AutoTokenizer

    raw = {
        d: json.loads((CONFIRM / f"raw/{d}.json").read_text())
        for d in ("counterfact", "zsre")
    }
    tests = {
        "counterfact": json.loads(
            (CONFIRM / "external_counterfact_n1000.json").read_text()
        )["facts"],
        "zsre": json.loads((CONFIRM / "external_zsre_n1000.json").read_text())["facts"],
    }
    dev = build_dev(
        raw["counterfact"],
        raw["zsre"],
        {f["subject"] for fs in tests.values() for f in fs},
    )
    items = {}
    for f in dev + tests["counterfact"] + tests["zsre"]:
        items[(f["subject"], f["probe"])] = None

    model_id = json.loads(MANIFEST_PATH.read_bytes())["models"]["base"]["id"]
    tok = AutoTokenizer.from_pretrained(model_id, padding_side="left")
    model = AutoModelForCausalLM.from_pretrained(
        model_id, dtype=torch.bfloat16, device_map={"": 0}
    )
    model.eval()
    keys = list(items)
    out = {}
    for start in range(0, len(keys), args.batch):
        chunk = keys[start : start + args.batch]
        prompts = [
            tok.apply_chat_template(
                [
                    {"role": "system", "content": SYSTEM},
                    {"role": "user", "content": USER.format(subject=s, probe=p)},
                ],
                add_generation_prompt=True,
                tokenize=False,
            )
            for s, p in chunk
        ]
        enc = tok(prompts, return_tensors="pt", padding=True).to(model.device)
        with torch.no_grad():
            gen = model.generate(
                **enc,
                max_new_tokens=160,
                do_sample=False,
                pad_token_id=tok.eos_token_id,
            )
        texts = tok.batch_decode(
            gen[:, enc["input_ids"].shape[1] :], skip_special_tokens=True
        )
        for (s, p), t in zip(chunk, texts):
            out[f"{s}\t{p}"] = {"raw": t, "keys": parse(t, p, s)}
        print(f"{min(start + args.batch, len(keys))}/{len(keys)}", flush=True)
    n_keys = [len(v["keys"]) for v in out.values()]
    report = {
        "prereg": "SS78",
        "n_prompts": len(out),
        "mean_keys": sum(n_keys) / len(n_keys),
        "no_keys": sum(k == 0 for k in n_keys),
        "keys": out,
    }
    Path(args.out).write_text(json.dumps(report, ensure_ascii=False, indent=1))
    print(json.dumps({k: v for k, v in report.items() if k != "keys"}))


if __name__ == "__main__":
    main()
